// frontend/packages/project-gateway/src/db/schema-cache.ts
var SCHEMA_CACHE_MAX = 50;
function createSchemaCache(load, max2 = SCHEMA_CACHE_MAX) {
  const entries = new Map;
  return {
    get(versionId, schemaKey) {
      const hit = entries.get(versionId);
      if (hit) {
        entries.delete(versionId);
        entries.set(versionId, hit);
        return hit;
      }
      const loading = load(schemaKey);
      entries.set(versionId, loading);
      loading.catch(() => {
        if (entries.get(versionId) === loading)
          entries.delete(versionId);
      });
      while (entries.size > max2) {
        const oldest = entries.keys().next().value;
        if (oldest === undefined)
          break;
        entries.delete(oldest);
      }
      return loading;
    }
  };
}

// frontend/packages/project-gateway/src/db/runtime.ts
function createDbRuntime(adapters) {
  const schemas3 = createSchemaCache((key) => adapters.schemas.load(key));
  let loading = null;
  const load = () => {
    loading ??= Promise.all([
      Promise.resolve().then(() => (init_dist7(), exports_dist)),
      Promise.resolve().then(() => (init_dist8(), exports_dist2)),
      Promise.resolve().then(() => (init_api2(), exports_api))
    ]).then(([orm, policy, server]) => ({
      ZenStackClient: orm.ZenStackClient,
      PolicyPlugin: policy.PolicyPlugin,
      RPCApiHandler: server.RPCApiHandler
    }));
    return loading;
  };
  return {
    async schemaOf(resolved) {
      const schema2 = await schemas3.get(resolved.versionId, resolved.schemaKey);
      if (resolved.realtime) {
        if (!adapters.turso)
          throw new Error("Realtime capture requires a database connector");
        const db = await adapters.turso.connect(resolved.db);
        await ensureRealtimeCapture(db, captureOptionsOf(schema2, resolved));
      }
      return schema2;
    },
    async policyClient({
      schema: schema2,
      db,
      actor,
      appSlug,
      isAnonymous,
      plugins = [],
      skipMetadata = false
    }) {
      if (!skipMetadata)
        await ensureRoleGrantMetadata(db, []);
      const { ZenStackClient: ZenStackClient2, PolicyPlugin: PolicyPlugin2 } = await load();
      let transaction;
      let client = new ZenStackClient2(schema2, {
        dialect: new LibsqlDialect({
          client: db,
          observeTransaction: (tx) => {
            transaction = tx;
          }
        })
      }).$use(new PolicyPlugin2).$use(manualRoleProvenancePlugin(actor.id, actor.permissions, () => transaction));
      for (const plugin of plugins)
        client = client.$use(plugin);
      return client.$setAuth({
        id: actor.id,
        globalUserId: actor.globalUserId,
        appSlug,
        permissions: actor.permissions.map((name3) => ({ name: name3 })),
        isAnonymous,
        blockedUserIds: actor.blockedUserIds
      });
    },
    async rpcHandler(schema2) {
      const { RPCApiHandler: RPCApiHandler2 } = await load();
      return new RPCApiHandler2({ schema: schema2 });
    }
  };
}

