// frontend/packages/project-gateway/src/notifications/send.ts
function registerServerNotificationRoutes(app, adapters) {
  app.post("/v1/notifications/send", bodyLimit({
    maxSize: REQUEST_BODY_MAX_BYTES,
    onError: () => {
      throw new GatewayError("PAYLOAD_TOO_LARGE", "request body too large");
    }
  }), async (c2) => {
    if (c2.req.header("origin") !== undefined)
      throw new GatewayError("FORBIDDEN", "server route only");
    const claims = await adapters.signer.verifyService(bearerOf(c2));
    const current = await adapters.services.current(claims.cid);
    if (!current)
      throw new GatewayError("UNAUTHENTICATED", "service credential unavailable");
    if (current.projectId !== claims.aud || current.appSlug !== claims.app || current.environment !== claims.env || current.sessionId !== (claims.br ?? null) || current.previewSessionId !== (claims.pv ?? null)) {
      throw new GatewayError("TOKEN_SCOPE_MISMATCH", "service scope changed");
    }
    if (!claims.permissions.includes("notifications.send") || !current.servicePermissions.includes("notifications.send")) {
      throw new GatewayError("FORBIDDEN", "notification permission required");
    }
    const parsed = notificationSendRequestSchema.safeParse(await jsonBody(c2));
    if (!parsed.success)
      throw new GatewayError("VALIDATION_FAILED", "invalid notification request");
    const request = parsed.data;
    const recipients = [...new Set(request.to)];
    const db = await adapters.turso.connect(current.db);
    const users = await findProjectUsers(db, recipients);
    if (users.length !== recipients.length)
      throw new GatewayError("VALIDATION_FAILED", "recipient outside project");
    const userIds = users.map((user) => platformUserIdOf(user.globalUserId));
    if (userIds.some((id) => !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id))) {
      throw new GatewayError("VALIDATION_FAILED", "unsupported recipient");
    }
    const result = await adapters.notifications.emit({
      projectId: claims.aud,
      environment: claims.env,
      sessionId: claims.br ?? null,
      previewSessionId: claims.pv ?? null,
      templateKey: request.template,
      userIds,
      params: Object.fromEntries(Object.entries(request.params).map(([key, value]) => [key, String(value)])),
      sourceKey: `service:${crypto.randomUUID()}`,
      actorId: null,
      dedupeKey: request.dedupeKey ?? null
    });
    if ("error" in result)
      throw new GatewayError(result.error, "notification refused");
    if (result.limited > 0 && result.recipients === 0)
      throw new GatewayError("RATE_LIMITED", "recipient notification limit exceeded");
    return c2.json({ recipients: result.recipients });
  });
}

